entries[5629] = { ["name"] = "Hammerfausthandschuhe", ["text"] = "Wird beim Aufheben gebunden\nHände Leder\n48 Rüstung\n+3 Stärke\n+3 Beweglichkeit\nHaltbarkeit 25 / 25\nVerkaufspreis:" }
