entries[5631] = { ["name"] = "Wuttrank", ["text"] = "Klassen: Krieger\nBenötigt Stufe 4\nBenutzen: Erhöht Wut um 20 bis 40. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[5632] = { ["name"] = "Trank der feigen Flucht", ["text"] = "Benötigt Stufe 15\nBenutzen: Ihr lauft voll Furcht in hohem Tempo ziellos vor einem in der Nähe befindlichen Feind davon. Wenn keine Feinde in der Nähe sind, steht Ihr still und starr vor Furcht. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[5633] = { ["name"] = "Großer Wuttrank", ["text"] = "Klassen: Krieger\nBenötigt Stufe 25\nBenutzen: Erhöht Wut um 30 bis 60. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[5634] = { ["name"] = "Trank der freien Aktion", ["text"] = "Benötigt Stufe 20\nBenutzen: Macht Euch 30 Sek. lang immun gegen betäubungs- und bewegungseinschränkende Effekte. Bereits bestehende Effekte dieser Art werden nicht entfernt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[5635] = { ["name"] = "Scharfe Klaue", ["text"] = "Verkaufspreis:" }
entries[5636] = { ["name"] = "Zierliche Feder", ["text"] = "Verkaufspreis:" }
entries[5637] = { ["name"] = "Großer Fangzahn", ["text"] = "Verkaufspreis:" }
entries[5638] = { ["name"] = "Toxinvernebler", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: In der Nähe des Flughafens der Venture Co. platzieren." }
entries[5639] = { ["name"] = "Gefüllte Jadephiole", ["text"] = "Questgegenstand\nEinzigartig" }
entries[5640] = { ["name"] = "Rezept: Wuttrank", ["text"] = "Benötigt Alchimie (60)\nBenutzen: Lehrt Euch die Herstellung eines Wuttranks.\nVerkaufspreis:\nWuttrank\nKlassen: Krieger\nBenötigt Stufe 4\nBenutzen: Erhöht Wut um 20 bis 40. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Scharfe Klaue (2), Leere Phiole" }
entries[5641] = { ["name"] = "Rezept: Trank der feigen Flucht", ["text"] = "Benötigt Alchimie (125)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der feigen Flucht.\nVerkaufspreis:\nTrank der feigen Flucht\nBenötigt Stufe 15\nBenutzen: Ihr lauft voll Furcht in hohem Tempo ziellos vor einem in der Nähe befindlichen Feind davon. Wenn keine Feinde in der Nähe sind, steht Ihr still und starr vor Furcht. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Zierliche Feder , Königsblut , Verbleite Phiole" }
entries[5642] = { ["name"] = "Rezept: Trank der freien Aktion", ["text"] = "Benötigt Alchimie (150)\nBenutzen: Lehrt Euch die Herstellung eines Tranks der freien Aktion.\nVerkaufspreis:\nTrank der freien Aktion\nBenötigt Stufe 20\nBenutzen: Macht Euch 30 Sek. lang immun gegen betäubungs- und bewegungseinschränkende Effekte. Bereits bestehende Effekte dieser Art werden nicht entfernt. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Schwarzmaulöl (2), Würgetang , Verbleite Phiole" }
entries[5643] = { ["name"] = "Rezept: Großer Wuttrank", ["text"] = "Benötigt Alchimie (175)\nBenutzen: Lehrt Euch die Herstellung eines starken Wuttranks.\nVerkaufspreis:\nGroßer Wuttrank\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Erhöht Wut um 30 bis 60. (2 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Großer Fangzahn , Königsblut , Verbleite Phiole" }
entries[5644] = { ["name"] = "Foliant des Wasserherbeizauberns", ["text"] = "Klassen: Magier\nBenötigt Stufe 4\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 1).\nZaubert 20 Flaschen Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes Wasser\nHerbeigezauberter Gegenstand\nBenutzen: Stellt im Verlauf von 18 Sek. insgesamt 151 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[5645] = { ["name"] = "Gefüllte Turmalinphiole", ["text"] = "Questgegenstand\nEinzigartig" }
entries[5646] = { ["name"] = "Phiole mit gesegnetem Wasser", ["text"] = "Questgegenstand\nEinzigartig" }
entries[5647] = { ["name"] = "Foliant des Blinzelns", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Blinzeln' (Rang 1).\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungen und Banden.\nVerkaufspreis:" }
entries[5648] = { ["name"] = "Foliant der Frostrüstung III", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Frostrüstung' (Rang 3).\nErhöht die Rüstung um 200. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\nVerkaufspreis:" }
entries[5649] = { ["name"] = "Foliant des Blizzards", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Blizzard' (Rang 1).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 Sek. lang insgesamt ( 26 * 8) Frostschaden.\nVerkaufspreis:" }
entries[5650] = { ["name"] = "Foliant des Wasserherbeizauberns III", ["text"] = "Klassen: Magier\nBenötigt Stufe 20\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 3).\nZaubert 20 Flaschen geläutertes Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nHerbeigezaubertes geläutertes Wasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 15\nBenutzen: Stellt im Verlauf von 24 Sek. insgesamt 835 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
