entries[5654] = { ["name"] = "Sofort wirkendes Toxin", ["text"] = "Klassen: Schurke\nBenötigt Stufe 24\nBenutzen: Überzieht ein Schwert oder einen Dolch mit Gift, das 30 Minuten lang wirkt.\nBei jedem Schlag besteht die Chance, den Feind zu vergiften und ihm sofort 10-30 Punkte Schaden zuzufügen.\nVerkaufspreis:" }
entries[5655] = { ["name"] = "Zaumzeug einer kastanienbraunen Stute", ["text"] = "Wird beim Aufheben gebunden\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 30\nBenötigt Reiten (75)\nBenutzen: Beschwört eine reitbare kastanienbraune Stute oder gibt sie frei. (3 Sek. Abklingzeit)" }
