entries[5672] = { ["name"] = "Buchband: Exorzismus", ["text"] = "Klassen: Paladin\nBenötigt Stufe 20\nBenutzen: Lehrt 'Exorzismus' (Rang 1).\nVerursacht 90 bis 102 Heiligschaden an einem untoten oder dämonischen Ziel.\nVerkaufspreis:" }
entries[5673] = { ["name"] = "Buchband: Exorzismus II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 28\nBenutzen: Lehrt 'Exorzismus' (Rang 2).\nVerursacht 160 bis 180 Heiligschaden an einem untoten oder dämonischen Ziel.\nVerkaufspreis:" }
entries[5674] = { ["name"] = "Buchband: Exorzismus III", ["text"] = "Klassen: Paladin\nBenötigt Stufe 36\nBenutzen: Lehrt 'Exorzismus' (Rang 3).\nVerursacht 227 bis 255 Heiligschaden an einem untoten oder dämonischen Ziel.\nVerkaufspreis:" }
entries[5675] = { ["name"] = "Kristallisierte Schuppen", ["text"] = "Questgegenstand" }
entries[5676] = { ["name"] = "Buchband: Untote spüren", ["text"] = "Klassen: Paladin\nBenötigt Stufe 20\nBenutzen: Lehrt 'Untote spüren'.\nZeigt den Aufenthaltsort aller in der Nähe befindlichen Untoten auf der Minikarte an, bis abgebrochen wird. Es kann immer nur jeweils eine Art des Fährtenlesens benutzt werden.\nVerkaufspreis:" }
entries[5677] = { ["name"] = "Buchband: Untote vertreiben", ["text"] = "Klassen: Paladin\nBenötigt Stufe 24\nBenutzen: Lehrt 'Untote vertreiben' (Rang 1).\nDer anvisierte untote Feind wird bis zu 10 Sek. lang zur Flucht gezwungen. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Ziel zur Flucht gezwungen werden.\nVerkaufspreis:" }
entries[5679] = { ["name"] = "Buchband: Siegel der Weisheit III", ["text"] = "Klassen: Paladin\nBenötigt Stufe 36\nBenutzen: Lehrt 'Siegel der Weisheit' (Rang 3).\nVerkaufspreis:" }
entries[5680] = { ["name"] = "Buchband: Siegel des Schutzes II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 20\nBenutzen: Lehrt 'Siegel des Schutzes' (Rang 2).\nEin anvisiertes Gruppenmitglied ist 8 Sek. lang vor allen körperlichen Angriffen geschützt, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein. Einmal geschützt, kann das Ziel 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden.\nVerkaufspreis:" }
entries[5681] = { ["name"] = "Ätzblutsaft", ["text"] = "Questgegenstand" }
entries[5682] = { ["name"] = "Buchband: Untote vertreiben II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 38\nBenutzen: Lehrt 'Untote vertreiben' (Rang 2).\nDer anvisierte untote Feind wird bis zu 15 Sek. lang zur Flucht gezwungen. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Ziel zur Flucht gezwungen werden.\nVerkaufspreis:" }
entries[5683] = { ["name"] = "Buchband: Gottesschild II", ["text"] = "Klassen: Paladin\nBenötigt Stufe 50\nBenutzen: Lehrt 'Gottesschild' (Rang 2).\nSchützt den Paladin 12 Sek. lang vor allen Schäden und Zaubern, erhöht jedoch die Zeit zwischen seinen Angriffen um 100%. Einmal geschützt, kann der Paladin 1 Min. lang nicht erneut durch Gottesschild, Göttlicher Schutz oder Segen des Schutzes unverwundbar gemacht werden oder Zornige Vergeltung nutzen.\nVerkaufspreis:" }
entries[5684] = { ["name"] = "Buchband: Siegel der Rettung", ["text"] = "Klassen: Paladin\nBenötigt Stufe 22\nBenutzen: Lehrt 'Siegel der Rettung' (Rang 1).\nBelegt ein Gruppenmitglied mit einem Segen und verringert dabei jegliche erzeugte Bedrohung 10 Min. lang um 30%. Spieler können pro Paladin immer nur mit einem einzigen Segen belegt sein.\nVerkaufspreis:" }
entries[5685] = { ["name"] = "Buchband: Erlösung", ["text"] = "Klassen: Paladin\nBenötigt Stufe 40\nBenutzen: Lehrt 'Erlösung'.\nVerkaufspreis:" }
