entries[5694] = { ["name"] = "NG-5-Sprengstoff (Rot)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt NG-5-Ladung ein (Rot)." }
entries[5695] = { ["name"] = "NG-5-Sprengstoff (Blau)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt NG-5-Ladung ein (Blau)." }
entries[5696] = { ["name"] = "Schrifttafel des Schocks", ["text"] = "Klassen: Schamane\nBenötigt Stufe 4\nBenutzen: Lehrt 'Schock' (Rang 1).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 25 bis 28 Schaden zu.\nVerkaufspreis:" }
entries[5697] = { ["name"] = "Schrifttafel des Totems der Heilung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 6\nBenutzen: Lehrt 'Totem der Heilung' (Rang 1).\nBeschwört 2 Min. lang ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Gruppenmitglieder im Umkreis von 20 Metern alle 2 Sek. um 6 heilt.\nVerkaufspreis:" }
entries[5698] = { ["name"] = "Schrifttafel des Blitzschlagschildes", ["text"] = "Klassen: Schamane\nBenötigt Stufe 8\nBenutzen: Lehrt 'Blitzschlagschild' (Rang 1).\nDer Zaubernde ist von 3 Kugelblitzen umgeben. Wenn der Zaubernde von einem Nahkampf-, Fernkampf- oder Zauberangriff getroffen wird, erleidet der Angreifende 13 Naturschaden. Dies kostet einen Kugelblitz. Es wird immer nur ein einzelner Kugelblitz alle paar Sekunden abgefeuert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein. (3.5s Abklingzeit)\nVerkaufspreis:" }
entries[5699] = { ["name"] = "Schrifttafel des Geisterwolfs", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Geisterwolf' (Rang 1).\nVerwandelt den Schamanen in einen Geisterwolf und erhöht sein Tempo um 40%. Kann nur draußen verwendet werden.\nVerkaufspreis:" }
entries[5700] = { ["name"] = "Schrifttafel des Totems der Heilung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Totem der Heilung' (Rang 2).\nBeschwört 2 Min. lang ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Gruppenmitglieder im Umkreis von 20 Metern alle 2 Sek. um 8 heilt.\nVerkaufspreis:" }
entries[5701] = { ["name"] = "Schrifttafel des Totem des Wachens", ["text"] = "Klassen: Schamane\nBenötigt Stufe 14\nBenutzen: Lehrt 'Totem des Wachens'.\nBeschwört 5 Min. lang ein unbewegliches Totem des Wachens mit 100 Gesundheit zu Euren Füßen, das die Sicht auf die in der Nähe befindlichen Bereiche ermöglicht und vor Feinden warnt, die es angreifen. Mit einem Rechtsklick auf den Stärkungszauber kann zwischen dem Blickwinkel des Totems und dem Blickwinkel des Schamanen gewechselt werden.\nVerkaufspreis:" }
entries[5702] = { ["name"] = "Schrifttafel des aufstachelnden Totems II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 18\nBenutzen: Lehrt 'Aufstachelndes Totem' (Rang 2).\nBeschwört 15 Sek. lang ein Totem der Steinklaue mit 150 Gesundheit zu Füßen des Zaubernden, das Kreaturen im Umkreis von 8 Metern durch Spott dazu bringt, es anzugreifen. Es besteht eine Chance von 50%, dass Gegner, die das Totem angreifen, 3 Sek. lang betäubt werden.\nVerkaufspreis:" }
entries[5703] = { ["name"] = "Schrifttafel des Donnerknalls", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Donnerknall' (Rang 1).\nDröhnt in der Nähe befindliche Feinde mit Donner zu, erhöht die Zeit zwischen ihren Angriffen 10 Sek. lang um 10% und fügt ihnen 10 Schaden zu. Diese Fähigkeit verursacht zusätzliche Bedrohung und wirkt auf maximal 4 Ziele.\nVerkaufspreis:" }
entries[5704] = { ["name"] = "Schrifttafel der Wasseratmung", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Wasseratmung'.\nErmöglicht dem Ziel 10 Min. lang das Atmen unter Wasser.\nVerkaufspreis:" }
entries[5705] = { ["name"] = "Schrifttafel des Totems der Heilung III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Totem der Heilung' (Rang 3).\nBeschwört 2 Min. lang ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Gruppenmitglieder im Umkreis von 20 Metern alle 2 Sek. um 10 heilt.\nVerkaufspreis:" }
entries[5706] = { ["name"] = "Schrifttafel des Schlangentotems III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Totem der Schlange' (Rang 3).\nBeschwört 40 Sek. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 19 bis 25 Punkt(e) Feuerschaden anrichtet.\nVerkaufspreis:" }
entries[5707] = { ["name"] = "Schrifttafel der Fernsicht", ["text"] = "Klassen: Schamane\nBenötigt Stufe 26\nBenutzen: Lehrt 'Fernsicht'.\nWechselt die Ansicht des Zaubernden zum Zielort. Hält 1 Min. lang an. Kann nur draußen verwendet werden.\nVerkaufspreis:" }
entries[5708] = { ["name"] = "Schrifttafel der Astralgestalt", ["text"] = "Klassen: Schamane\nBenötigt Stufe 24\nBenutzen: Lehrt 'Astralgestalt' (Rang 1).\nVerkaufspreis:" }
entries[5709] = { ["name"] = "Schrifttafel des Wasserwandelns", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Wasserwandeln'.\nErmöglicht dem befreundeten Ziel, 10 Min. lang auf Wasser zu wandern. Jeglicher erlittene Schaden hebt den Effekt wieder auf.\nVerkaufspreis:" }
entries[5710] = { ["name"] = "Schrifttafel des Totems der Heilung IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 28\nBenutzen: Lehrt 'Totem der Heilung' (Rang 4).\nVerkaufspreis:" }
entries[5711] = { ["name"] = "Schrifttafel des Geisterwolfs II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Geisterwolf' (Rang 2).\nVerkaufspreis:" }
entries[5712] = { ["name"] = "Schrifttafel des Schlangentotems IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Totem der Schlange' (Rang 4).\nBeschwört 45 Sek. lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 26 bis 34 Punkt(e) Feuerschaden anrichtet.\nVerkaufspreis:" }
entries[5713] = { ["name"] = "Schrifttafel des Donnerblitzes", ["text"] = "Klassen: Schamane\nBenötigt Stufe 32\nBenutzen: Lehrt 'Donnerblitz'.\nSchützt das befreundete Ziel gegen Furcht. Der nächste Furchteffekt gegen das Ziel ist erfolglos, dabei wird der Zauberschutz verbraucht. Hält 3 Min. lang an.\nVerkaufspreis:" }
entries[5714] = { ["name"] = "Schrifttafel des Totems der Einschnürung II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 34\nVerkaufspreis:" }
entries[5715] = { ["name"] = "Schrifttafel des Gewittersturms III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Gewittersturm' (Rang 3).\nVerkaufspreis:" }
entries[5716] = { ["name"] = "Schrifttafel der Wiederherstellung VI", ["text"] = "Klassen: Schamane\nBenötigt Stufe 40\nBenutzen: Lehrt 'Große Welle der Heilung' (Rang 2).\nHeilt ein befreundetes Ziel um 552 bis 639.\nVerkaufspreis:" }
