entries[5719] = { ["name"] = "Zauberfoliant des Lebenssaugers II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Blutsauger' (Rang 2).\nÜberträgt alle 1 Sek. 17 Gesundheit vom Ziel auf den Zaubernden. Hält 5 Sek. lang an.\nVerkaufspreis:" }
entries[5720] = { ["name"] = "Zauberfoliant des Fluchs von Mannoroth II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Fluch der Schwäche' (Rang 2).\nDie Nahkampfangriffskraft des Ziels wird 2 Min. lang um 41 reduziert. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein.\nVerkaufspreis:" }
entries[5721] = { ["name"] = "Zauberfoliant der Zaubersteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Zauberstein herstellen'.\nStellt einen Zauberstein für den Zaubernden her. Wenn er angelegt und benutzt wird, bannt der Zauberstein alle schädlichen magischen Effekte vom Zaubernden. Außerdem erhöht das Anlegen des Zaubersteins Eure kritische Zaubertrefferwertung um 8.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:\nZauberstein\nHerbeigezauberter Gegenstand\nWird beim Aufheben gebunden\nEinzigartig\nRelikt\nBenötigt Stufe 36\nBenutzen: Bannt alle schädlichen magischen Effekte vom Zaubernden. (3 Min Abklingzeit)\nAnlegen: Erhöht Eure kritische Zaubertrefferwertung um 8.\nBenötigt Seelensplitter" }
entries[5722] = { ["name"] = "Zauberfoliant des Manaentzugs II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Mana entziehen' (Rang 2).\nÜberträgt alle 1 Sek. 68 Mana vom Ziel auf den Zaubernden. Hält 5 Sek. lang an.\nVerkaufspreis:" }
entries[5723] = { ["name"] = "Zauberfoliant des Fluchs von Sargeras III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 36\nBenutzen: Lehrt 'Fluch der Pein' (Rang 3).\nVerflucht das Ziel mit Pein und fügt 24 Sek. lang insgesamt 324 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein.\nVerkaufspreis:" }
entries[5724] = { ["name"] = "Zauberfoliant des Fluchs der Sprachen", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 22\nBenutzen: Lehrt 'Fluch der Sprachen' (Rang 1).\nZwingt das Ziel, Dämonisch zu sprechen, und verlangsamt die Zauberzeit um 50%. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem Ziel aktiv sein. Hält 30 Sek. lang an.\nVerkaufspreis:" }
entries[5725] = { ["name"] = "Zauberfoliant der Pestilenz III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 38\nBenutzen: Lehrt 'Verderbnis' (Rang 3).\nVerdirbt das Ziel und verursacht 18 Sek. lang insgesamt 222 Schattenschaden.\nVerkaufspreis:" }
entries[5726] = { ["name"] = "Zauberfoliant der großen Blutsteinherstellung", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 38\nBenutzen: Lehrt 'Großen Gesundheitsstein herstellen'.\nVerkaufspreis:" }
entries[5727] = { ["name"] = "Zauberfoliant des Manatrichters", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Manatrichter'.\nVerkaufspreis:" }
entries[5728] = { ["name"] = "Zauberfoliant des Feuerregens II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Feuerregen' (Rang 2).\nLässt einen feurigen Regen niedergehen, der 8 Sek. lang Feinde im Wirkungsbereich mit insgesamt ( 98 * 4) Feuerschaden verbrennt.\nVerkaufspreis:" }
entries[5729] = { ["name"] = "Zauberfoliant der Furcht III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 40\nBenutzen: Lehrt 'Furcht' (Rang 3).\nErfüllt den Feind mit Furcht, woraufhin er bis zu 20 Sek. lang voller Furcht flüchtet. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden.\nVerkaufspreis:" }
entries[5730] = { ["name"] = "Buch der Verjüngung", ["text"] = "Klassen: Druide\nBenötigt Stufe 4\nBenutzen: Lehrt 'Verjüngung' (Rang 1).\nHeilt beim Ziel 12 Sek. lang insgesamt 32 Schaden.\nVerkaufspreis:" }
