entries[6045] = { ["name"] = "Pläne: Eisengegengewicht", ["text"] = "Benötigt Schmiedekunst (165)\nBenutzen: Lehrt Euch die Herstellung eines Eisengegengewichts zum Ausbalancieren einer Zweihandwaffe.\nVerkaufspreis:\nEisengegengewicht\nBenutzen: Bringt ein Gegengewicht an einem Zweihandschwert, einem Zweihandstreitkolben, einer Zweihandaxt oder an einer Stangenwaffe an und erhöht die Angriffstempowertung um 20.\nVerkaufspreis:\nBenötigt Eisenbarren (4), Grober Schleifstein (2), Geringer Mondstein" }
entries[6046] = { ["name"] = "Pläne: Stahlwaffenkette", ["text"] = "Benötigt Schmiedekunst (190)\nBenutzen: Lehrt Euch die Herstellung einer Stahlwaffenkette.\nVerkaufspreis:\nStahlwaffenkette\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 50% verringert. Ist nicht mit ähnlichen Effekten stapelbar.\nVerkaufspreis:\nBenötigt Stahlbarren (8), Schwerer Schleifstein (2), Schweres Leder (4)" }
